To convert Markdown formatted text to HTML, you can use a library like `cpp-md-parser` or `commonmark`. Here's an example using `cpp-md-parser` and `pugixml` for generating HTML:

First, install the required libraries using package manager like vcpkg:

```sh
vcpkg install cpp-md-parser pugixml
```

Now, create a C++ file with the following content:

```cpp
#include <iostream>
#include <string>
#include <cppmark/parser.h>
#include <pugixml.hpp>

std::string markdown_to_html(const std::string& markdown) {
    using namespace cppmark;
    using namespace pugi;

    // Initialize parser
    MarkdownParser parser;

    // Parse markdown
    std::unique_ptr<ParserOutput> tree = parser.parse(markdown, markdown.size());

    // Create HTML document
    xml_document doc;
    doc.set_base_url(".");

    // Create HTML elements
    xml_node root = doc.append_child(node_declare("html", {"xmlns": "http://www.w3.org/1999/xhtml"}));
    xml_node head = root.append_child(node_declare("head"));
    xml_node title = head.append_child(node_declare("title", {"text": "Output Title"}));
    xml_node body = root.append_child(node_declare("body"));

    // Process parsed markdown tree
    process_markdown_tree(tree.get(), body);

    // Convert tree to XML string
    std::stringstream ss;
    doc.save(ss, 4);

    // Extract HTML string from XML
    std::string html = ss.str();
    size_t start_pos = html.find("<html xmlns=\"http://www.w3.org/1999/xhtml\">");
    size_t end_pos = html.find("</html>");

    html = html.substr(start_pos, end_pos - start_pos);

    return html;
}

void process_markdown_tree(const ParserOutput* tree, xml_node html_node) {
    for (size_t i = 0; i < tree->num_nodes; ++i) {
        const Node* node = tree->nodes[i];

        switch (node->type) {
            case NodeType::Text:
                html_node.append_child(node_declare("span", {"class": "text"})
                                          .append_child(node_declare("tspan", {"text": node->text})));
                break;
            case NodeType::SoftBreak:
                html_node.append_child(node_declare("br"));
                break;
            case NodeType::HardBreak:
                html_node.append_child(node_declare("p"));
                break;
            case NodeType::Header:
                html_node = create_header_element(html_node, node->level);
                break;
            case NodeType::Emphasis:
                html_node = create_emphasis_element(html_node, node->text);
                break;
            case NodeType::Strong:
                html_node = create_strong_element(html_node, node->text);
                break;
            case NodeType::Link:
                html_node = create_link_element(html_node, node->text, node->url);
                break;
            case NodeType::Image:
                html_node = create_image_element(html_node, node->alt, node->url);
                break;
            case NodeType::Code:
                html_node = create_code_element(html_node, node->text);
                break;
            case NodeType::CodeBlock:
                html_node = create_code_block_element(html_node, node->info.info.language);
                process_markdown_tree(node->children, html_node);
                break;
            case NodeType::List:
                html_node = create_list_element(html_node, node->ordered, node->start);
                process_markdown_tree(node->children, html_node);
                break;
            case NodeType::ListItem:
                html_node = create_list_item_element(html_node);
                process_markdown_tree(node->children, html_node);
                break;
            default:
                break;
        }
    }
}

xml_node create_header_element(xml_node parent, int level) {
    xml_node header = parent.append_child(node_declare("h" + std::to_string(level)));
    return header;
}

xml_node create_emphasis_element(xml_node parent, const std::string& text) {
    xml_node emphasis = parent.append_child(node_declare("em"));
    emphasis.append_child(node_declare("tspan", {"text": text}));
    return emphasis;
}

xml_node create_strong_element(xml_node parent, const std::string& text) {
    xml_node strong = parent.append_child(node_declare("strong"));
    strong.append_child(node_declare("tspan", {"text": text}));
    return strong;
}

xml_node create_link_element(xml_node parent, const std::string& link_text, const std::string& link_url) {
    xml_node link = parent.append_child(node_declare("a", {"href": link_url}));
    xml_node text = link.append_child(node_declare("span", {"class": "link-text"}));
    text.append_child(node_declare("tspan", {"text": link_text}));
    return link;
}

xml_node create_image_element(xml_node parent, const std::string& alt, const std::string& src) {
    xml_node img = parent.append_child(node_declare("img", {"src": src, "alt": alt}));
    return img;
}

xml_node create_code_element(xml_node parent, const std::string& text) {
    xml_node code = parent.append_child(node_declare("code"));
    xml_node pre = code.append_child(node_declare("pre"));
    xml_node text_node = pre.append_child(node_declare("tspan", {"class": "code-text", "text": text}));
    return code;
}

xml_node create_code_block_element(xml_node parent, const std::string& language) {
    xml_node code_block = parent.append_child(node_declare("pre", {"class": "code-block", "xml:space": "preserve"}));
    xml_node code = code_block.append_child(node_declare("code", {"class": "code", "lang": language}));
    return code_block;
}

xml_node create_list_element(xml_node parent, bool ordered, int start) {
    xml_node list = parent.append_child(node_declare("ul", {"class": ordered ? "ordered" : "unordered"}});
    if (ordered) {
        list.append_child(node_declare("ol", {"start": start}));
    }
    return list;
}

xml_node create_list_item_element(xml_node parent) {
    xml_node list_item = parent.append_child(node_declare("li"));
    return list_item;
}

int main() {
    std::string markdown = R"(
# Heading 1
## Heading 2
**Bold text**
*Italic text*
[Link](http://example.com)
![Image](image.jpg)
```
code
function helloWorld() {
  console.log("Hello World!");
}
```
1. List item 1
2. List item 2
)";

    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

